const LIDS = '640,1056,734,673,708,748,770,10153,10152';
const out = []; let cur = [];
for (let i = 959968986; i <= 959969984; i++) { cur.push(i); if (cur.length === 300) { out.push({ json: { ids: cur.join(','), lids: LIDS } }); cur = []; } }
if (cur.length) { out.push({ json: { ids: cur.join(','), lids: LIDS } }); }
return out;

const cfg = $('Config').first().json;
const LING = ['daniel@dgmultilingualservices.com','silke.luehrmann@gmx.de','ilaria.roncaglia@gmail.com','root-translations@outlook.com','qrcodelocalization@gmail.com','mteixeira@sacradomus.com','bruno@bsttranslations.com','michal.tosza@translators.org.pl','roxanamoldovan25@gmail.com','dmluciahorea@gmail.com','austra.muizniece@gmail.com','julius.valkiunas@gmail.com','silis.martins@gmail.com','arandatrad@gmail.com','sara.guinot.trad@gmail.com','mteres@terestraducciones.com'];
const NAME = { es:'Spanish (Spain)', it:'Italian', fr:'French', pt:'Portuguese (Brazil)', pl:'Polish', ro:'Romanian', lv:'Latvian', lt:'Lithuanian' };
const EXTRA = {
 it: 'Prefer a neutral rephrasing; the Italian style guide allows o/a (convinto/a) only when no neutral rephrasing exists, so a string already using o/a correctly may stay unchanged.',
 fr: 'The French style guide allows (e) (convaincu(e)) only when no epicene rephrasing exists; a string already using (e) correctly may stay unchanged. Adjectives agreeing with other nouns (débat ouvert) are fine. Keep the non-breaking spaces before : ; ? ! and inside « ».',
 pt: 'Brazilian Portuguese, address as você with 3rd-person verbs. List items describing how others see the reader (e.g. "Compassivo e mente aberta") must be neutral too ("Pessoa compassiva e de mente aberta").',
 pl: 'Polish addresses the reader as ty: avoid gendered adjectives and past-tense forms for the reader (sceptyczny, otwarty, skłonny, ostrożny, współczujący, -łeś/-łaś); rephrase with verbs, nouns ("osoba …") or impersonal constructions.',
 ro: 'Romanian informal tu: rephrase gendered forms (convins, deschis, atras, sceptic) with verbs or neutral constructions (e.g. "Te conving mai puțin:", "O persoană …").',
 lv: 'Latvian formal jūs: never use gender-marked endings for the reader, and never (-a) style endings; rephrase with verbs, nouns ("cilvēks, kas …") or neutral constructions.',
 lt: 'Lithuanian jūs: avoid gender-marked participles/adjectives for the reader and (-a)/(-i) endings; rephrase with verbs, nouns (žmogus, kuris …) or impersonal constructions.'
};
const NL = String.fromCharCode(10);
const rows = [];
for (const it of $('Fetch').all()) { for (const k of ((it.json.body || {}).keys || [])) { if (k.is_archived) { continue; } let en = ''; const tr = {}; for (const t of (k.translations || [])) { const v = typeof t.translation === 'string' ? t.translation : ''; if (t.language_iso === 'en') { en = v; } else { tr[t.language_iso] = { v: v, e: t.modified_by_email || '' }; } } rows.push({ id: k.key_id, n: (typeof k.key_name === 'object') ? (k.key_name.web || k.key_name.other) : k.key_name, en: en, tr: tr }); } }
const out = []; const skippedLing = [];
function item(r, L) { const t = r.tr[L]; if (!t || !t.v.trim()) { return null; } if (LING.indexOf(t.e) >= 0) { skippedLing.push({ id: r.id, lang: L }); return null; } return { id: r.id, key: r.n.replace(/^components::members::profile::|^pages::/, ''), en: r.en, t: t.v }; }
const NOOP = 'Return {} only.';
for (const L of cfg.langs) {
  const manualIds = Object.keys(cfg.manual || {}).filter(function (k) { return k.split('|')[1] === L; }).map(function (k) { return Number(k.split('|')[0]); });
  if (manualIds.length) { const ks = rows.filter(function (r) { return manualIds.indexOf(r.id) >= 0; }).map(function (r) { return item(r, L); }).filter(Boolean); out.push({ json: { lang: L, part: 'manual', n: ks.length, keys: ks, system: NOOP, user: '{}' } }); }
  const cand = (cfg.cand || {})[L] || [];
  if (cand.length) {
    const ks = rows.filter(function (r) { return cand.indexOf(r.id) >= 0 && manualIds.indexOf(r.id) < 0; }).map(function (r) { return item(r, L); }).filter(Boolean);
    const sys = ['You are a senior ' + NAME[L] + ' reviewer for Personality.co (Political Views test: a report addressed to the reader).', 'These strings were flagged because they MAY describe or address the READER with a grammatically gendered form (masculine by default). For each one: if it does, rewrite it gender-neutrally and naturally, changing as little as possible; if the gendered word agrees with another noun (debate, la libertà, una persona, people in general), it is fine: leave it out.', EXTRA[L] || '', 'Keep placeholders like [%1$s:name] and tags like <span>…</span> exactly. Keep all other wording, punctuation and typography unchanged. Lead-in + list item structure must keep working.', 'Return ONLY a JSON object {"<key_id>": "<corrected full translation>"} containing ONLY strings you changed. Return {} if nothing needs changing.'].join(NL);
    out.push({ json: { lang: L, part: 'gender', n: ks.length, keys: ks, system: sys, user: 'Flagged strings (' + ks.length + '):' + NL + JSON.stringify(ks.map(function (x) { return { key_id: String(x.id), key: x.key, en: x.en, t: x.t }; })) } });
  }
  if (L === 'fr') {
    const done = cand.concat(manualIds);
    const ks = rows.filter(function (r) { return done.indexOf(r.id) < 0 && r.tr.fr && r.tr.fr.v.indexOf('\u2019') >= 0; }).map(function (r) { return item(r, L); }).filter(Boolean);
    for (let i = 0; i < ks.length; i += 200) { out.push({ json: { lang: L, part: 'apostrophes', n: ks.slice(i, i + 200).length, keys: ks.slice(i, i + 200), system: NOOP, user: '{}' } }); }
  }
}
for (const o of out) { o.json.skipped_linguist = skippedLing.length; o.json.rows = rows.length; }
return out;

function allRuns(name) { const out = []; for (let i = 0; i < 2000; i++) { let items; try { items = $(name).all(0, i); } catch (e) { break; } if (!items || !items.length) { break; } for (const it of items) { out.push(it.json); } } return out; }
const v = allRuns('Validate'); const w = allRuns('Write');
const per = {};
v.forEach(function (x, i) { const r = w[i] || {}; per[x.lang] = per[x.lang] || { changed: 0, gender: 0, apostrophe: 0, write_fail: 0, errors: [], rejected: 0 }; const p = per[x.lang]; p.changed += x.changed; x.changes.forEach(function (c) { if (c.why.indexOf('gender') >= 0) { p.gender++; } if (c.why.indexOf('apostrophe') >= 0) { p.apostrophe++; } }); if (x.changed && r.statusCode !== 200) { p.write_fail += x.changed; } if (x.err) { p.errors.push(x.part + ': ' + x.err); } p.rejected += x.rejected.length; });
const changes = []; v.forEach(function (x) { x.changes.forEach(function (c) { if (c.why.indexOf('gender') >= 0) { changes.push(Object.assign({ lang: x.lang }, c)); } }); });
return [{ json: { per_lang: per, gender_changes: changes } }];

const b = $('Loop').item.json;
const cfg = $('Config').first().json;
const r = $json || {};
let map = {}; let err = null;
if (r.choices && r.choices[0]) { const raw = String(r.choices[0].message.content || ''); const s = raw.indexOf('{'), e = raw.lastIndexOf('}'); try { map = JSON.parse(raw.slice(s, e + 1)); } catch (x) { err = 'parse: ' + String(x).slice(0, 100); } } else { err = 'OpenAI: ' + JSON.stringify(r.error || r).slice(0, 150); }
const PH = /\[%[^\]]*\]|%\d*\$?[sd]|\{\{[^}]+\}\}/g; const TAG = /<\/?[A-Za-z][^>]*>/g;
const keys = []; const changes = []; const rejected = [];
for (const k of b.keys) {
  let t = k.t; let why = [];
  const man = (cfg.manual || {})[k.id + '|' + b.lang];
  const g = man || map[String(k.id)];
  if (typeof g === 'string' && g.trim() && g.trim() !== k.t.trim()) {
    const cand = g.trim();
    const okP = (k.en.match(PH) || []).sort().join('|') === (cand.match(PH) || []).sort().join('|');
    const okT = (k.en.match(TAG) || []).join('|').toLowerCase() === (cand.match(TAG) || []).join('|').toLowerCase();
    const ratio = cand.length / Math.max(1, k.t.length);
    if (okP && okT && ratio > 0.6 && ratio < 1.6) { t = cand; why.push(man ? 'manual' : 'gender'); } else { rejected.push({ id: k.id, why: !okP ? 'placeholder' : !okT ? 'tag' : 'length', t: cand.slice(0, 120) }); }
  }
  if (b.lang === 'fr' && t.indexOf('\u2019') >= 0) { t = t.replace(/\u2019/g, "'"); why.push('apostrophe'); }
  if (t !== k.t) { keys.push({ key_id: k.id, translations: [{ language_iso: b.lang, translation: t, is_unverified: true }] }); changes.push({ id: k.id, why: why.join('+'), before: k.t.slice(0, 160), after: t.slice(0, 160) }); }
}
return { json: { lang: b.lang, part: b.part, n: b.n, changed: keys.length, err: (b.system === 'Return {} only.') ? null : err, rejected: rejected, changes: changes, body: { keys: keys } } };
